+fn adc(a: u64, b: u64, carry: u64) -> (u64, u64) {
+    // Every caller passes `b <= 1` or `carry <= 1`, so at most one of the two
+    // additions overflows and the outgoing carry is 0 or 1.
+    let (sum, carry1) = a.overflowing_add(b);
+    let (sum, carry2) = sum.overflowing_add(carry);
+    (sum, u64::from(carry1 | carry2))
+}

